<script>
(()=>{
  "use strict";
  const TAU=Math.PI*2;
  const canvas=document.getElementById('scene');
  const ctx=canvas.getContext('2d');
  const phaseEl=document.getElementById('phase');
  const clockEl=document.getElementById('clock');
  const barEl=document.getElementById('bar');

  const dayLength=10000;   // ms for a full cycle
  let w,h,horizonY,dpr;

  let skyFar=[],skyMid=[];
  let stars=[],clusters=[],glints=[],clouds=[],birds=[];
  let far=[]; let mid=[[]];
  let waterBaseTop,waterWaveY,waterGlowY,waterRippleRows=[];
  let sunX=0,sunY=0,mx=0,my=0;
  let dayDark=0,nightAmount=0,cloudAlpha=0;
  let curTime=0,lastPhase='',lastClock='';

  /* ---------- helpers ---------- */
  const lerp=(a,b,f)=>a+(b-a)*f;
  const clamp=(v,a,b)=>v<a?a:v>b?b:v;
  const sat=(f,a,b)=> f<=a?0:f>=b?1:(f-a)/(b-a);
  const rand=(a,b)=>a+Math.random()*(b-a);
  const pick=a=>a[(Math.random()*a.length)|0];
  function rgb(c){return c[0]<<16|c[1]<<8|c[2];}
  function readColor(css){
    const m=css.match(/rgba?\(([^)]+)\)/);
    const p=m[1].split(',').map(s=>parseFloat(s));
    return[r[p.length===4?p[0]:0],g,p[2]];var r=p[0],g=p[1];
  }
  function mix(a,b,t){return[lerp(a[0],b[0],t),lerp(a[1],b[1],t),lerp(a[2],b[2],t)];}
  function rgba(c,a){return`rgba(${c[0]|0},${c[1]|0},${c[2]|0},${a})`;}
  function line(a,b,c,d){ctx.beginPath();ctx.moveTo(a,b);ctx.lineTo(c,d);ctx.stroke();}
  function circle(x,y,r){ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.fill();}
  function rr(x,y,wd,ht,rad){
    rad=Math.min(rad,wd/2,ht/2);
    ctx.beginPath();
    ctx.moveTo(x+rad,y);
    ctx.arcTo(x+wd,y,x+wd,y+ht,rad);
    ctx.arcTo(x+wd,y+ht,x,y+ht,rad);
    ctx.arcTo(x,y+ht,x,y,rad);
    ctx.arcTo(x,y,x+wd,y,rad);
    ctx.closePath();
  }
  function buildLayer(maxH,minH,minW,maxW,tier){
    const colFar=tier===0,colMid=tier===1,seed=Math.random();
    const colx=Math.random()*.7+(colMid?(1-seed)*.28:seed*.12);
    const col=[mix(colFar?[66,84,120]:[46,54,80],[96,76,104],colx)];
    const windows=[];let x=0;
    while(x<w){
      const bw=rand(minW,maxW)*(colMid?1:0.85);
      const bh=(minH+Math.pow(Math.random(),1.9)*(maxH-minH))*(colFar?0.85:1);
      const top=horizonY-bh;
      if(colMid){
        const cols=Math.max(2,Math.floor(bw/15)),rows=Math.max(2,Math.floor(bh/23));
        const cw=(bw-10)/cols,ch=(bh-6)/rows;
        for(let c=0;c<cols;c++)for(let r=0;r<rows;r++)
          windows.push({x:x+5+c*(bw-10)/cols,y:top+4+r*(bh-6)/rows,
                        w:cw*.62,h:ch*.6,
                        lit:Math.random()<(colFar?0.22:0.3),
                        t:Math.random(),sp:0.3+Math.random()*1.5});
      }
      if(tier===1)
        if(Math.random()<0.28)
          for(let k=1;k<=1+((Math.random()*2)|0);k++){
            const sw=bw*nearRatio(k),t=top-k*4;
            ctx.fillStyle=col;ctx.fillRect(x+(bw-sw)/2,t,sw,4);
          }
        else if(Math.random()<0.12){
          const bw2=rand(30,70),bh2=rand(60,150),t=horizonY-bh2+(bh2-bh)*.4;
          ctx.fillStyle=col;ctx.fillRect(x+bw+2,t,bw2,bh2);
          if(Math.random()<0.5)for(let k=1;k<=2;k++){
            const tw=bw2*.7,t2=t-k*4;ctx.fillStyle=col;ctx.fillRect(x+bw+2+(bw2-tw)/2,t2,tw,4);
          }
      } else
        ctx.fillRect(x,top,bw,bh);
      x+=bw+(colFar?rand(1,4):rand(6,20));
    }
    return col;
  }
  function nearRatio(k){return Math.max(0.15,1-k*0.3);}

  function spawnBird(at){
    const dir=Math.random()<0.5?1:-1,sw=Math.random()*.45+.4;
    birds.unshift({x:at?rand(-80,w+80):dir>0?-40:w+40,y:rand(h*.12,h*.4),
                   base:clamp(5+Math.random()*6,4,10),ph:Math.random()*6,sp:sw});
    if(birds.length>7)birds.pop();
  }

  /* ---------- world build ---------- */
  function layerSky(){
    const pts=[[0,[6,10,30]],[0.02,[15,22,62]],[0.045,[30,42,102]],[0.075,[64,74,128]],
               [0.11,[126,94,112]],[0.13,[172,104,110]],[0.15,[232,120,96]],[0.18,[255,148,94]],
               [0.21,[255,186,118]], [0.28,[247,206,150]],[0.33,[214,224,216]],
               [0.40,[154,194,224]],[0.50,[96,162,206]],[0.60,[132,196,224]],
               [0.67,[196,226,236]],[0.73,[244,206,150]],[0.78,[252,176,108]],
               [0.83,[238,128,86]],[0.87,[196,86,92]],[0.905,[120,62,96]],
               [0.94,[54,42,92]],[0.97,[22,22,58]],[1,[6,10,30]]];
    skyFar=[];skyMid=[];
    for(let i=0;i<=100;i++){
      const f=i/100;let a=pts[0],b=pts[pts.length-1];
      for(let k=0;k<pts.length-1;k++)if(f>=pts[k][0]&&f<=pts[k+1][0]){a=pts[k];b=pts[k+1];break;}
      const t=(f-a[0])/((b[0]-a[0])||1),r=mix(a[1],b[1],t);
      skyFar[i]=rgb(r);skyMid[i]=rgb(mix(r,[0,0,0],.5));
    }
  }
  function makeClouds(){
    clouds=[];const n=Math.round(clamp(w/260,4,7));
    for(let i=0;i<n;i++){
      const puffs=[],x0=Math.random()*(w+300)-150,y=rand(h*.08,h*.34),s=rand(.7,1.35);
      for(let k=0;k<7;k++)puffs.push({dx:(Math.random()-.5)*130*s,dy:(Math.random()-.5)*28*s,r:rand(18,48)*s});
      clouds.push({x:x0,y,s,puffs,sp:rand(.28,.7)});
    }
  }
  function makeStars(){
    const n=Math.round(w*h/6200);stars=[];
    for(let i=0;i<n;i++){const y=Math.random()*(horizonY-h*.05)-6;
      stars.push({x:Math.random()*w,y,r:Math.random()<.9?rand(.4,1.3):rand(1.2,2.1),
                  b:rand(.4,1),tw:rand(0,TAU),sp:rand(.5,2.6)});}
  }
  function build(){
    w=canvas.width/dpr;h=canvas.height/dpr;
    horizonY=h*0.6;
    layerSky();
    makeStars();
    clusters=[];
    for(let i=0;i<14;i++){const cx=Math.random()*w,cy=Math.random()*(horizonY-h*.15),
        nb=3+((Math.random()*4)|0);const a=[];
      for(let k=0;k<nb;k++)a.push({dx:(Math.random()-.5)*60,dy:(Math.random()-.5)*40,r:rand(.5,1.6),b:rand(.4,1),tw:rand(0,TAU),sp:rand(.5,2.2)});
      clusters.push({cx,cy,a});}
    glints=[];
    for(let i=0;i<28;i++)glints.push({x:Math.random()*w,y:horizonY-8-Math.random()*h*.3,r:rand(1,2.2),tw:rand(0,TAU),sp:rand(1,3)});
    makeClouds();
    far=[];mid=[[[],[]]];
    far.push(buildLayer(h*.34,h*.13,26,64,0));
    let mxw=0,i=0;
    while(mxw<w*1.4){
      const col=buildLayer(h*.5,h*.16,40,110,1);
      i=(i+1)%2;mid[i].push(col);mxw+=w*.7;
    }
    const wt=horizonY;waterBaseTop=wt;
    waterWaveY=new Float32Array(w);
    for(let x=0;x<w;x++)waterWaveY[x]=wt+Math.sin(x*.02)*1.4+Math.sin(x*.05+1.3)*.8;
    waterGlowY=wt+10;
    waterRippleRows=[];const rows=Math.round((h-wt)/13);
    for(let r=0;r<rows;r++)waterRippleRows.push({y:wt+6+r*13,amp:1.5+r*.12,ph:r*.6,sp:.6+r*.02});
    birds=[];for(let i=0;i<3;i++)spawnBird(true);
  }

  /* ---------- per-frame scene values ---------- */
  function computeScene(){
    const f=curTime;
    const dayFrac=(f+0.25)%1;
    const sunA=dayFrac*TAU-Math.PI/2;
    const alt=Math.sin(sunA);
    sunX=w*.5+Math.cos(sunA)*(w*.42);
    sunY=horizonY-alt*(horizonY-h*.06);
    const moonA=sunA+Math.PI;
    mx=w*.5+Math.cos(moonA)*(w*.42);
    my=horizonY-Math.sin(moonA)*(horizonY-h*.06);
    dayDark=1-sat(alt,-.12,.15);
    nightAmount=sat(-alt,.02,.28);
    cloudAlpha=clamp(1-dayDark*.5,.35,1);
  }

  /* ---------- drawing ---------- */
  function drawSky(){
    const idx=clamp((curTime*100)|0,0,100);
    const g=ctx.createLinearGradient(0,0,0,horizonY);
    g.addColorStop(0,'#'+skyMid[idx].toString(16).padStart(6,'0'));
    g.addColorStop(1,'#'+skyFar[idx].toString(16).padStart(6,'0'));
    ctx.fillStyle=g;ctx.fillRect(0,0,w,horizonY+2);
  }
  function drawStars(){
    if(nightAmount<=0.01)return;
    for(const s of stars){
      const a=nightAmount*s.b*(.55+.45*Math.sin(s.tw+curTime*s.sp));if(a<=0.02)continue;
      ctx.globalAlpha=a;ctx.fillStyle='#eaf1ff';circle(s.x,s.y,s.r);
    }
    for(const c of clusters)for(const p of c.a){
      const a=nightAmount*p.b*(.5+.5*Math.sin(p.tw+curTime*p.sp));if(a<=0.02)continue;
      ctx.globalAlpha=a;ctx.fillStyle='#cfe0ff';circle(c.cx+p.dx,c.cy+p.dy,p.r);
    }
    ctx.globalAlpha=1;
  }
  function drawGlints(){
    if(nightAmount<=0.02)return;
    for(const g of glints){
      const a=nightAmount*.5*(.4+.6*Math.abs(Math.sin(g.tw+curTime*g.sp)));if(a<=0.03)continue;
      ctx.strokeStyle=`rgba(200,220,255,${a})`;ctx.lineWidth=1;
      line(g.x-3,g.y,g.x+3,g.y);line(g.x,g.y-3,g.x,g.y+3);
    }
  }
  function drawCeleste(x,y,R,col,mul,dark){
    const g=ctx.createRadialGradient(x,y,0,x,y,R*2.6);
    g.addColorStop(0,rgba(col,.5*mul));g.addColorStop(.4,rgba(col,.2*mul));g.addColorStop(1,rgba(col,0));
    ctx.fillStyle=g;ctx.fillRect(x-R*2.6,y-R*2.6,R*5.2,R*5.2);
    const d=ctx.createRadialGradient(x-R*.3,y-R*.3,R*.2,x,y,R);
    d.addColorStop(0,rgba(mix(col,[255,255,255],.4),1));
    d.addColorStop(.7,rgba(col,1));
    d.addColorStop(1,rgba(dark?mix(col,[0,0,0],.35):col,.9));
    ctx.fillStyle=d;circle(x,y,R);
  }
  function drawSun(){
    if(sunY>horizonY+h*.07)return;
    const R=(horizonY-h*.06)*.05;
    const t=clamp((1-altSun())*.1,.0,.6); // helper below approximates near-noon brightness
    drawCeleste(sunX,clamp(sunY,-40,horizonY+40),R,[255,214,120],1+t,false);
  }
  function altSun(){return Math.sin(((curTime+0.25)%1)*TAU-Math.PI/2);}
  function drawMoon(){
    if(my>horizonY+h*.07)return;
    const R=(horizonY-h*.06)*.04;
    let m;
    if(nightAmount>0.5){const g=ctx.createRadialGradient(mx,my,0,mx,my,R*3.2);
      g.addColorStop(0,`rgba(180,205,255,${(nightAmount-.5)*.5})`);g.addColorStop(1,'rgba(180,205,255,0)');
      ctx.fillStyle=g;ctx.fillRect(mx-R*3.2,my-R*3.2,R*6.4,R*6.4);}
    ctx.globalCompositeOperation='source-over';
    m=ctx.createRadialGradient(mx-R*.3,my-R*.3,R*.2,mx,my,R);
    m.addColorStop(0,'#eef2fb');m.addColorStop(.7,'#cdd6ea');m.addColorStop(1,'#aeb6cd');
    ctx.fillStyle=m;circle(mx,my,R);
    ctx.save();ctx.beginPath();ctx.arc(mx,my,R,0,TAU);ctx.clip();
    ctx.fillStyle='rgba(120,130,160,.35)';
    for(const c of [[-.3,-.2,.35],[.25,.1,.28],[.05,.35,.22],[-.1,-.4,.18],[.4,-.35,.2]])
      circle(mx+c[0]*R,my+c[1]*R,c[2]*R);
    ctx.restore();
  }
  function moonPath(){
    const rx=(horizonY-h*.06)*.04;
    ctx.save();ctx.beginPath();ctx.arc(mx,my,rx,0,TAU);ctx.clip();
    ctx.fillStyle='#f6f3e3';ctx.fillRect(mx-2000,my-2000,rx*2+4000,4000);
    ctx.fillStyle='#0a1030';
    ctx.beginPath();ctx.arc(mx+(.28+nightAmount*.06)*rx,my-.12*rx,rx*1.02,0,TAU);ctx.fill();
    ctx.restore();
  }
  function sunGlow(){
    if(sunY>horizonY+h*.07)return;
    const R=(horizonY-h*.06);
    const col=mix([255,241,205],[255,120,80],dayDark);
    const st=Math.max(0,R-sunY)/R,strength=clamp(1-sunY/(R*.55),0,1)*(.25+.75*st);
    if(strength<=0.01)return;
    const g=ctx.createRadialGradient(sunX,horizonY,0,sunX,horizonY,R*1.1);
    g.addColorStop(0,rgba(col,.5*strength));g.addColorStop(.5,rgba(col,.18*strength));g.addColorStop(1,rgba(col,0));
    ctx.fillStyle=g;ctx.fillRect(0,0,w,horizonY+2);
  }
  function drawClouds(){
    const col=mix([255,255,255],[30,36,66],dayDark);
    for(const c of clouds){
      c.x+=c.sp*(1/60);if(c.x>w+200){c.x=-200;c.y=rand(h*.08,h*.34);}
      ctx.fillStyle=rgba(col,cloudAlpha*.5);
      for(const p of c.puffs)circle(c.x+p.dx,c.y+p.dy,p.r);
    }
  }
  function buildSilhouette(){
    ctx.beginPath();ctx.moveTo(0,horizonY);
    for(const col of far)for(const b of col)ctx.lineTo(b.x,horizonY-b.h);
    ctx.lineTo(w,horizonY);ctx.closePath();
  }
  function drawFar(){
    ctx.fillStyle=rgb(far[0]);buildSilhouette();ctx.fill();
    if(nightAmount>0.02){
      ctx.save();buildSilhouette();ctx.clip();
      ctx.fillStyle=`rgba(255,168,96,${nightAmount*.12})`;ctx.fillRect(0,0,w,horizonY);ctx.restore();
    }
  }
  function drawMid(){
    const off=curTime*w*.02;
    for(let i=0;i<2;i++){
      const c=mid[i][0];
      ctx.fillStyle=rgb(c);
      for(const b of mid[i])ctx.fillRect(b.x-off,horizonY-b.h,b.w,b.h);
      if(nightAmount>0.02){
        ctx.save();
        for(const b of mid[i]){ctx
